parameters.jsCode:
const raw = $json.choices[0].message.content;
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch(e) {
  parsed = { caption: raw, hashtags: '#pizza #food #delicious #italianfood' };
}
return [{
  json: {
    caption: parsed.caption || '',
    hashtags: parsed.hashtags || '#pizza',
    food_description: $('OpenAI Analyze Food').item.json.choices[0].message.content,
    photo_url: $('Build Photo URL').item.json.photo_url,
    chat_id: $('Build Photo URL').item.json.chat_id
  }
}];

const falResponse = $json;
const caption = $('Parse Caption and Hashtags').item.json.caption;
const hashtags = $('Parse Caption and Hashtags').item.json.hashtags;
const chatId = $('Parse Caption and Hashtags').item.json.chat_id;
const photoUrl = $('Parse Caption and Hashtags').item.json.photo_url;

let enhancedUrl = photoUrl;
if (falResponse.images && falResponse.images[0] && falResponse.images[0].url) {
  enhancedUrl = falResponse.images[0].url;
} else if (falResponse.image && falResponse.image.url) {
  enhancedUrl = falResponse.image.url;
}

const postId = Date.now().toString(36) + Math.random().toString(36).substr(2, 4);

const staticData = $getWorkflowStaticData('global');
staticData[postId] = {
  caption,
  hashtags,
  enhanced_image_url: enhancedUrl,
  chat_id: chatId
};

return [{ json: { post_id: postId, enhanced_image_url: enhancedUrl, caption, hashtags, chat_id: chatId } }];

parameters.text:
=Your post is ready!

Caption:
{{ $json.caption }}

Hashtags:
{{ $json.hashtags }}

Approve to post to Instagram, Facebook, TikTok and Google Business?

parameters.jsCode:
const callbackData = $json.callback_query.data;
const parts = callbackData.split('_');
const action = parts[0];
const postId = parts.slice(1).join('_');
const chatId = $json.callback_query.message.chat.id;
const callbackQueryId = $json.callback_query.id;

const staticData = $getWorkflowStaticData('global');
const postData = staticData[postId];

if (!postData && action === 'approve') {
  return [{ json: { action: 'error', post_id: postId, chat_id: chatId, callback_query_id: callbackQueryId, error: 'Post data not found' } }];
}

return [{ json: {
  action,
  post_id: postId,
  chat_id: chatId,
  callback_query_id: callbackQueryId,
  caption: postData ? postData.caption : '',
  hashtags: postData ? postData.hashtags : '',
  enhanced_image_url: postData ? postData.enhanced_image_url : ''
} }];

